const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const PROJECTS = {
  riga: { vertical: 'STEM', project: 'Riga' },
  rainier: { vertical: 'STEM', project: 'Rainier' },
  sequoia: { vertical: 'STEM', project: 'Sequoia' },
  starfish: { vertical: 'STEM', project: 'Starfish' },
  terminus: { vertical: 'Coding', project: 'Terminus' },
  paperbench: { vertical: 'Coding', project: 'PaperBench' },
  'paper bench': { vertical: 'Coding', project: 'PaperBench' },
  'sentinel ultra': { vertical: 'Coding', project: 'Sentinel Ultra' },
  'sentinal ultra': { vertical: 'Coding', project: 'Sentinel Ultra' },
};

function read(row, ...names) {
  const keys = Object.keys(row || {});
  for (const name of names) {
    const key = keys.find((candidate) => candidate.trim().toLowerCase() === name.toLowerCase());
    if (key && row[key] !== null && row[key] !== undefined) return row[key];
  }
  return '';
}

function text(value) {
  return String(value ?? '').trim();
}

function springverify(value) {
  const status = text(value).toLowerCase();
  if (!status) return null;
  if (status.includes('complete') || status.includes('verified') || status.includes('approved')) return 'done';
  if (status.includes('not started') || status.includes('pending') || status.includes('await')) return 'awaited';
  return null;
}

function remofirst(value) {
  const status = text(value).toLowerCase();
  if (!status) return null;
  if (status.includes('approved') || status.includes('verified')) return 'approved';
  if (status.includes('not started') || status.includes('not received') || status.includes('rejected')) return 'not_received';
  if (status.includes('pending') || status.includes('sent')) return 'pending';
  return null;
}

function contractStatus(signed, sent) {
  const signedText = text(signed).toLowerCase();
  const sentText = text(sent).toLowerCase();
  if (signedText && /signed|complete|yes|true/.test(signedText)) return 'signed';
  if (sentText && /not sent|not started|no/.test(sentText)) return 'not_signed';
  if (sentText && /sent|shared/.test(sentText)) return 'sent';
  return null;
}

const output = [];

for (const item of items) {
  const row = item.json;
  const email = text(read(row, 'Email', 'Personal Email')).toLowerCase();
  const status = text(read(row, 'Status')).toLowerCase();
  if (!EMAIL_RE.test(email) || status !== 'active') continue;

  const fullName = [text(read(row, 'First Name')), text(read(row, 'Last name', 'Last Name'))]
    .filter(Boolean)
    .join(' ');
  const sourceDomain = text(read(row, 'Domain'));
  const domain = /^(coding|stem|mojave)$/i.test(sourceDomain) ? null : sourceDomain;
  const projects = text(read(row, 'Project'))
    .split(/[,;/]+/)
    .map((value) => value.trim().toLowerCase().replace(/\s+/g, ' '))
    .filter(Boolean);

  const common = {
    p_email: email,
    p_full_name: fullName,
    p_client: 'Snorkel',
    p_domain: domain || null,
    p_bgv_id_status: springverify(read(row, 'CH Background Check')),
    p_remofirst_status: remofirst(read(row, 'RemoFirst Check')),
    p_contract_status: contractStatus(read(row, 'Contracts Signed'), read(row, 'Contract Sent')),
    p_is_offboarded_heuristic: false,
    p_source_sheet: 'Snorkel MainPaperBench Internal / PaperBench Live Candidates',
  };

  for (const sourceProject of projects) {
    const project = PROJECTS[sourceProject];
    if (!project) continue;
    output.push({ json: { ...common, p_vertical: project.vertical, p_project: project.project } });
  }
}

return output;
